import * as THREE from 'three/webgpu';
import { color, uniform, vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'footer-colophon';

  const W = 6.8;
  const H = 2.0;

  const disposables = [];
  const textMeshes = [];

  // --- Background band with vertical gradient ---
  const topColor = color('#121218');
  const bottomColor = color('#0b0b10');
  const vGrad = uv().y;
  const bgColorNode = mix(bottomColor, topColor, vGrad);

  const bgMaterial = new THREE.MeshStandardNodeMaterial();
  bgMaterial.colorNode = bgColorNode;
  bgMaterial.roughnessNode = uniform(0.6);
  bgMaterial.metalnessNode = uniform(0.2);
  disposables.push(bgMaterial);

  const bgGeo = new THREE.PlaneGeometry(W, H);
  disposables.push(bgGeo);
  const bgMesh = new THREE.Mesh(bgGeo, bgMaterial);
  bgMesh.position.set(0, 0, 0);
  group.add(bgMesh);

  // --- Hairline rules ---
  function makeHairline(y) {
    const geo = new THREE.PlaneGeometry(W, 0.006);
    const mat = new THREE.MeshStandardNodeMaterial();
    mat.colorNode = color('#23232b');
    mat.roughnessNode = uniform(0.4);
    mat.metalnessNode = uniform(0.3);
    disposables.push(geo, mat);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0, y, 0.001);
    group.add(mesh);
    return mesh;
  }

  const topHairline = makeHairline(H / 2);
  const legalHairline = makeHairline(-H / 2 + 0.375 + 0.25);

  // --- Accent bar under wordmark ---
  const accentGeo = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMat = new THREE.MeshStandardNodeMaterial();
  accentMat.colorNode = color('#ff2a38');
  accentMat.emissiveNode = vec3(1.4, 0.0, 0.0).mul(color('#ff2a38'));
  accentMat.roughnessNode = uniform(0.5);
  accentMat.metalnessNode = uniform(0.2);
  disposables.push(accentGeo, accentMat);
  const accentBar = new THREE.Mesh(accentGeo, accentMat);

  const leftX = -W / 2 + 1.0; // left column center approx (2.0 width block)
  const wordmarkY = H / 2 - 0.5;
  accentBar.position.set(leftX - 0.85, wordmarkY - 0.28, 0.001);
  group.add(accentBar);

  // --- Text content helper ---
  function addText(content, styleKey, x, y, colorHex) {
    const typo = config.visualSpec?.typography?.[styleKey] || {};
    const mesh = ctx.fontAtlas.createText(content, {
      font: typo.family || 'JetBrains Mono',
      fontSize: (typo.fontSize || 12) * 0.006,
      fontWeight: typo.fontWeight || 400,
      letterSpacing: typo.letterSpacing || 0,
      lineHeight: typo.lineHeight || 1.2,
      color: colorHex || '#e8ecf2',
    });
    mesh.position.set(x, y, 0.002);
    group.add(mesh);
    textMeshes.push(mesh);
    return mesh;
  }

  // Wordmark
  addText('NOVA ATELIER', 'wordmark', leftX - 1.0, wordmarkY, '#e8ecf2');

  // Columns
  const colStartX = leftX + 1.15;
  const colWidth = 1.2;
  const gutter = 0.375;
  const colTopY = H / 2 - 0.5;

  const columns = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const linkObjs = [];

  columns.forEach((col, i) => {
    const cx = colStartX + i * (colWidth + gutter);
    addText(col.header, 'column-header', cx, colTopY, '#8a8a92');
    col.links.forEach((linkText, j) => {
      const ly = colTopY - 0.3 - j * (0.13 * 1.8);
      const linkMesh = addText(linkText, 'link', cx, ly, '#e8ecf2');
      linkMesh.userData.baseColor = '#e8ecf2';
      linkMesh.userData.hoverColor = '#ff2a38';
      linkObjs.push(linkMesh);
    });
  });

  // Legal line
  addText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    'legal',
    -W / 2 + 0.1,
    -H / 2 + 0.15,
    '#8a8a92'
  );

  // --- Apply cinematic primitives (none configured but included for contract) ---
  const primitives = config.cinematicPrimitives || [];
  primitives.forEach((p) => {
    if (ctx.primitives && ctx.primitives[p.name]) {
      ctx.primitives[p.name](group, p.params);
    }
  });

  // --- Mount animation: fade-up ---
  group.position.set(
    config.scenePosition?.position?.[0] ?? 0,
    (config.scenePosition?.position?.[1] ?? 0) + 0.2,
    config.scenePosition?.position?.[2] ?? 0
  );
  group.traverse((child) => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: (config.scenePosition?.position?.[1] ?? 0),
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);

  const opacityTargets = [];
  group.traverse((child) => {
    if (child.material) opacityTargets.push(child.material);
  });
  opacityTargets.forEach((mat) => {
    tl.to(mat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  });

  // --- Handlers (hover behavior on links) ---
  group.userData.handlers = {
    onPointerMove: (event) => {
      // event.intersects expected to contain hit objects
      linkObjs.forEach((linkMesh) => {
        const isHover = event?.intersects?.some((hit) => hit.object === linkMesh);
        if (isHover) {
          gsap.to(linkMesh.position, { z: 0.02, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          if (linkMesh.material?.color) {
            gsap.to(linkMesh.material.color, {
              r: 1.0, g: 0.165, b: 0.22,
              duration: 0.14,
            });
          }
        } else {
          gsap.to(linkMesh.position, { z: 0.002, duration: 0.14, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          if (linkMesh.material?.color) {
            gsap.to(linkMesh.material.color, {
              r: 0.91, g: 0.925, b: 0.945,
              duration: 0.14,
            });
          }
        }
      });
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    disposables.forEach((d) => d.dispose && d.dispose());
    textMeshes.forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
      if (m.userData?.cleanup) m.userData.cleanup();
    });
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return group;
}
